"""Pydantic V2 schemas for PatchItem and PatchResponse."""
from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field


class PatchItem(BaseModel):
    """Structured code patch item generated by the Coder agent."""
    model_config = ConfigDict(extra="forbid")

    unified_diff: str = Field(..., description="Valid unified diff string")
    target_files: list[str] = Field(..., min_length=1, description="Relative file paths modified in the patch")
    base_commit_sha: str = Field(..., description="Target base Git commit SHA")
    file_hashes: dict[str, str] = Field(default_factory=dict, description="Pre-modification SHA-256 file hashes")
    summary: str = Field(..., description="Concise technical summary of the changes")
    revision: int = Field(default=1, ge=1, description="Monotonically increasing patch revision number")
    content_hash: str = Field(..., description="SHA-256 hash of the unified diff content computed by application")
    id: str | None = Field(default=None, description="Persisted database Patch ID")


class PatchResponse(BaseModel):
    """API response schema for a persisted patch revision."""
    model_config = ConfigDict(from_attributes=True)

    id: str
    run_id: str
    revision: int
    unified_diff: str
    target_files: list[str]
    summary: str
    content_hash: str
    validation_status: str
    created_at: datetime
